// Keep only meetings due within the reminder window; normalize fields
const cfg = $('CONFIG — Reminder Settings').first().json;
const minMin = parseInt(cfg.reminder_window_min_minutes || '55', 10);
const maxMin = parseInt(cfg.reminder_window_max_minutes || '65', 10);
const tz = cfg.instance_timezone || 'UTC';
const internalDomain = (cfg.internal_email_domain || '').toLowerCase().replace(/^@/, '');
const now = Date.now();

function toE164(raw) {
  if (!raw) return '';
  let d = String(raw).replace(/[^\d+]/g, '');
  if (d.startsWith('+')) return '+' + d.slice(1).replace(/\D/g, '');
  d = d.replace(/\D/g, '');
  if (d.length === 10) return '+1' + d; // bare 10-digit number -> assume US; adjust for your country
  return d ? '+' + d : '';
}
function fmtInTz(ms) {
  try {
    return new Intl.DateTimeFormat('en-US', { timeZone: tz, dateStyle: 'medium', timeStyle: 'short' }).format(new Date(ms));
  } catch (e) { return new Date(ms).toISOString(); }
}

const raw = $input.first().json.data || [];
const activities = Array.isArray(raw) ? raw : [];
const out = [];
for (const a of activities) {
  // Pipedrive returns due_date (YYYY-MM-DD) + due_time (HH:MM:SS) in UTC
  const dueStr = [a.due_date, a.due_time].filter(Boolean).join('T');
  const dueMs = Date.parse(dueStr.endsWith('Z') ? dueStr : dueStr + 'Z');
  if (!dueMs) continue;
  const minsUntil = (dueMs - now) / 60000;
  if (minsUntil < minMin || minsUntil > maxMin) continue;

  // Participants: drop internal attendees, keep the first external prospect
  const participants = Array.isArray(a.participants) ? a.participants : [];
  const external = participants.filter(p => {
    const email = (p.email || '').toLowerCase();
    return email && (!internalDomain || !email.endsWith('@' + internalDomain));
  });
  const person = a.person_id && typeof a.person_id === 'object' ? a.person_id : {};
  const prospect = external[0] || {};
  const email = prospect.email || (Array.isArray(person.email) ? (person.email[0] || {}).value : person.email) || '';
  if (internalDomain && email.toLowerCase().endsWith('@' + internalDomain)) continue;
  const phoneRaw = prospect.phone || (Array.isArray(person.phone) ? (person.phone[0] || {}).value : person.phone) || '';
  const org = a.org_id && typeof a.org_id === 'object' ? a.org_id.name : '';

  out.push({ json: {
    activity_id: String(a.id),
    prospect_name: prospect.name || person.name || '',
    prospect_email: email,
    prospect_phone: toE164(phoneRaw),
    meeting_title: a.subject || 'Meeting',
    due_at: fmtInTz(dueMs),
    due_at_iso: new Date(dueMs).toISOString(),
    person_org: org || '',
    context_topic: (a.note || a.subject || '').slice(0, 200),
    status: 'NEW',
  }});
}
return out;

// Skip meetings already reminded (send-once guard by activity_id)
const sent = new Set(
  $('Read Reminder Log').all()
    .filter(i => (i.json.status || i.json.Status || '') === 'REMINDER_SENT')
    .map(i => String(i.json.activity_id || '').trim())
    .filter(Boolean)
);
const fresh = $('Normalize Meetings — Window + Timezone').all()
  .map(i => i.json)
  .filter(m => m.activity_id && !sent.has(String(m.activity_id).trim()));
return fresh.map(m => ({ json: m }));

