{
  "sms_text": "short reminder text, under 320 characters, naming the meeting time and one context detail",
  "email_subject": "short specific subject line naming the meeting",
  "email_body": "3-5 short sentences, same facts as the SMS, no invented details",
  "personalization_notes": "which provided fact(s) you used for personalization, or 'none available'"
}

