// Tag the SMS outcome while preserving the meeting fields
const src = $('AI Agent — Write Reminder').all();
return $input.all().map((item, i) => {
  const base = (src[i] || src[0] || { json: {} }).json;
  const failed = Boolean(item.json.error) || item.json.statusCode >= 400;
  return { json: { ...base, sms_result: failed ? 'FAILED' : 'SENT' } };
});

// Tag the email outcome while preserving the meeting fields
const src = $('AI Agent — Write Reminder').all();
return $input.all().map((item, i) => {
  const base = (src[i] || src[0] || { json: {} }).json;
  const failed = Boolean(item.json.error);
  return { json: { ...base, email_result: failed ? 'FAILED' : 'SENT' } };
});

// One row per meeting: REMINDER_SENT if at least one channel succeeded
const byId = {};
for (const item of $input.all()) {
  const j = item.json;
  const id = String(j.activity_id || '');
  if (!id) continue;
  byId[id] = { ...(byId[id] || {}), ...j };
}
return Object.values(byId).map(m => {
  const ok = m.sms_result === 'SENT' || m.email_result === 'SENT';
  return { json: {
    activity_id: m.activity_id,
    prospect_name: m.prospect_name || '',
    prospect_email: m.prospect_email || '',
    prospect_phone: m.prospect_phone || '',
    meeting_title: m.meeting_title || '',
    due_at: m.due_at || '',
    status: ok ? 'REMINDER_SENT' : 'FAILED',
    sms_result: m.sms_result || 'FAILED',
    email_result: m.email_result || 'FAILED',
    sent_at: new Date().toISOString(),
  }};
});

// Summarize this run for the Telegram digest
const items = $('Evaluate Send Results').all().map(i => i.json);
const sent = items.filter(m => m.status === 'REMINDER_SENT');
const failed = items.filter(m => m.status === 'FAILED');
let lines = [`⏰ *Meeting Reminders — ${new Date().toISOString().slice(0, 10)}*`, ``];
if (!items.length) {
  lines.push(`No meetings were due in the reminder window this run.`);
} else {
  lines.push(`✅ ${sent.length} reminder(s) sent · ❌ ${failed.length} failed`, ``);
  for (const m of sent.slice(0, 10)) lines.push(`• ${m.prospect_name || m.prospect_email} — ${m.meeting_title} (${m.due_at}) [SMS: ${m.sms_result}, Email: ${m.email_result}]`);
  for (const m of failed.slice(0, 10)) lines.push(`• FAILED: ${m.prospect_name || m.prospect_email} — ${m.meeting_title} (${m.due_at})`);
}
return [{ json: { digest: lines.join('\n'), sent: sent.length, failed: failed.length } }];
